INSERT INTO kairo.questions (id, subject, topic, subtopic, learning_objective, concepts_tested, prerequisite_concepts, difficulty_rating, cognitive_level, estimated_solving_time_sec, reading_load, calculation_load, distractors, skills_assessed, source, year, exam_body, related_question_ids, stem, options, correct_option, explanation, lifecycle_state, empirical_stats) VALUES
('mathematics_0056', 'Mathematics', 'Differentiation', 'Product Rule at a Point', NULL, '[{"weight": 1, "conceptId": "40mgg1"}]'::jsonb, '{}', 3, 'application', 90, 'low', 'heavy', '[{"option": "A", "explanation": "π results from a sign error in applying the product rule to 2x·cos2x.", "misconceptionId": "sign_error"}, {"option": "C", "explanation": "π/2 results from forgetting the factor of 4 that comes from the chain rule on cos2x and sin2x.", "misconceptionId": "formula_recall_error"}, {"option": "D", "explanation": "-π/2 combines the same missing chain-rule factor with the correct sign.", "misconceptionId": "formula_recall_error"}]'::jsonb, '{}', 'jamb_past_question', 2000, 'JAMB', '{}', 'If y = 2xcos2x - sin2x, find \(\frac{dy}{dx}\) when x = \(\frac{π}{4}\)', '[{"label": "A", "text": "π", "isCorrect": false}, {"label": "B", "text": "-π", "isCorrect": true}, {"label": "C", "text": "\\(\\frac{π}{2}\\)", "isCorrect": false}, {"label": "D", "text": "-\\(\\frac{π}{2}\\)", "isCorrect": false}]'::jsonb, 'B', 'dy/dx = 2cos2x - 4x·sin2x - 2cos2x = -4x·sin2x (product rule on 2x·cos2x, minus derivative of sin2x). At x=π/4: sin(π/2)=1, so dy/dx = -4(π/4)(1) = -π.', 'live', '{"totalAttempts": 0, "correctCount": 0, "avgResponseTimeMs": 0, "distractorSelectionCounts": {}}'::jsonb),
('mathematics_0057', 'Mathematics', 'Inequalities', 'Quadratic Inequalities', NULL, '[{"weight": 1, "conceptId": "w103dg"}]'::jsonb, '{}', 2, 'application', 90, 'low', 'moderate', '[{"option": "A", "explanation": "''x<-2 or x>1'' incorrectly applies the outside-the-roots rule that belongs to a ''>0'' inequality, not ''<0''.", "misconceptionId": "overgeneralized_rule"}, {"option": "B", "explanation": "''x>2 or x<-1'' uses the wrong roots (2 and -1 instead of the correct 1 and -2) as well as the wrong inequality direction.", "misconceptionId": "arithmetic_slip"}, {"option": "C", "explanation": "''-1<x<2'' uses the correct ''between the roots'' logic but with the roots'' signs flipped.", "misconceptionId": "sign_error"}]'::jsonb, '{}', 'jamb_past_question', 2000, 'JAMB', '{}', 'Solve the inequality 2 - x > x\(^2\).', '[{"label": "A", "text": "x < -2 or x > 1", "isCorrect": false}, {"label": "B", "text": "x > 2 or x< -1", "isCorrect": false}, {"label": "C", "text": "-1 < x < 2", "isCorrect": false}, {"label": "D", "text": "-2 < x < 1", "isCorrect": true}]'::jsonb, 'D', '2-x > x² rearranges to x²+x-2 < 0, which factors as (x+2)(x-1) < 0, giving -2 < x < 1.', 'live', '{"totalAttempts": 0, "correctCount": 0, "avgResponseTimeMs": 0, "distractorSelectionCounts": {}}'::jsonb),
('mathematics_0058', 'Mathematics', 'Circles', 'Circumradius of an Equilateral Triangle', NULL, '[{"weight": 1, "conceptId": "dzvgpm"}]'::jsonb, '{}', 3, 'application', 90, 'low', 'heavy', '[{"option": "A", "explanation": "2/3 cm comes from using the inradius formula (a/(2√3)) instead of the circumradius formula, with an extra arithmetic slip.", "misconceptionId": "formula_recall_error"}, {"option": "B", "explanation": "2 cm comes from doubling the correct radius, perhaps confusing radius with diameter.", "misconceptionId": "confused_similar_concepts"}, {"option": "D", "explanation": "3 cm comes from mistakenly using R = a instead of R = a/√3.", "misconceptionId": "formula_recall_error"}]'::jsonb, '{}', 'jamb_past_question', 2000, 'JAMB', '{}', 'An equilateral triangle of side √3cm is inscribed in a circle. Find the radius of the circle.', '[{"label": "A", "text": "2/3 cm", "isCorrect": false}, {"label": "B", "text": "2 cm", "isCorrect": false}, {"label": "C", "text": "1 cm", "isCorrect": true}, {"label": "D", "text": "3 cm", "isCorrect": false}]'::jsonb, 'C', 'For an equilateral triangle of side a, the circumradius R = a/√3. With a=√3, R = √3/√3 = 1 cm.', 'live', '{"totalAttempts": 0, "correctCount": 0, "avgResponseTimeMs": 0, "distractorSelectionCounts": {}}'::jsonb),
('mathematics_0059', 'Mathematics', 'Mensuration', 'Volume of a Frustum (Similar Triangles for Height)', NULL, '[{"weight": 1, "conceptId": "mathmen2"}]'::jsonb, '{}', 3, 'application', 90, 'low', 'heavy', '[{"option": "A", "explanation": "8.0 m results from mis-setting the similar-triangle ratio as 2/(5-2) instead of 2/5.", "misconceptionId": "formula_recall_error"}, {"option": "B", "explanation": "8.4 m results from an arithmetic slip while solving the similar-triangles equation.", "misconceptionId": "arithmetic_slip"}, {"option": "C", "explanation": "9.0 m results from treating the ratio as 2/5 of the total height directly, rather than solving the similar-triangle proportion properly.", "misconceptionId": "overgeneralized_rule"}]'::jsonb, '{}', 'jamb_past_question', 2000, 'JAMB', '{}', 'A frustrum of pyramid with square base has its upper and lower sections as squares of sizes 2m and 5m respectively and the distance between them 6m. Find the height of the pyramid from which the frustrum was obtained.', '[{"label": "A", "text": "8.0 m", "isCorrect": false}, {"label": "B", "text": "8.4 m", "isCorrect": false}, {"label": "C", "text": "9.0 m", "isCorrect": false}, {"label": "D", "text": "10.0 m", "isCorrect": true}]'::jsonb, 'D', 'By similar triangles, if h is the height from the apex to the smaller (2m) square, h/(h+6) = 2/5, giving 5h=2h+12, h=4. Total pyramid height = h+6 = 10m.', 'live', '{"totalAttempts": 0, "correctCount": 0, "avgResponseTimeMs": 0, "distractorSelectionCounts": {}}'::jsonb),
('mathematics_0060', 'Mathematics', 'Indices', 'Simplifying Exponential Expressions', NULL, '[{"weight": 1, "conceptId": "mathind1"}]'::jsonb, '{}', 2, 'application', 90, 'low', 'moderate', '[{"option": "A", "explanation": "2 (the truncated duplicate option, a scraping artifact) results from forgetting to distribute the coefficient 4 across 2^(n-1).", "misconceptionId": "arithmetic_slip"}, {"option": "B", "explanation": "The other ''2'' entry (also a scraping duplicate) reflects the same missing-distribution error as option A.", "misconceptionId": "arithmetic_slip"}, {"option": "D", "explanation": "1/4 results from inverting the correct final ratio.", "misconceptionId": "sign_error"}]'::jsonb, '{}', 'jamb_past_question', 2000, 'JAMB', '{}', 'Simplify \(\frac{3(2^{n+1}) - 4(2^{n-1})}{2^{n+1} - 2^n}\)', '[{"label": "A", "text": "2", "isCorrect": false}, {"label": "B", "text": "2", "isCorrect": false}, {"label": "C", "text": "4", "isCorrect": true}, {"label": "D", "text": "1/4", "isCorrect": false}]'::jsonb, 'C', 'Numerator: 3(2·2ⁿ) - 4(2ⁿ/2) = 6·2ⁿ - 2·2ⁿ = 4·2ⁿ. Denominator: 2·2ⁿ - 2ⁿ = 2ⁿ. The ratio is 4·2ⁿ/2ⁿ = 4.', 'live', '{"totalAttempts": 0, "correctCount": 0, "avgResponseTimeMs": 0, "distractorSelectionCounts": {}}'::jsonb),
('mathematics_0061', 'Mathematics', 'Percentages', 'Compound Interest (Present Value)', NULL, '[{"weight": 1, "conceptId": "m82i1l"}]'::jsonb, '{}', 3, 'application', 90, 'low', 'heavy', '[{"option": "A", "explanation": "N112,000.50 results from using simple interest (P(1+0.25×3)) instead of compound interest.", "misconceptionId": "formula_recall_error"}, {"option": "B", "explanation": "N96,000.00 results from dividing by (1.25)² instead of (1.25)³ (using 2 years instead of 3).", "misconceptionId": "arithmetic_slip"}, {"option": "C", "explanation": "N85,714.28 results from dividing 150,000 by 1.75 (mistakenly treating 25% as a single one-time addition rather than compounding it three times).", "misconceptionId": "formula_recall_error"}]'::jsonb, '{}', 'jamb_past_question', 2000, 'JAMB', '{}', 'A man wishes to keep his money in a savings deposit at 25% compound interest so that after three years he can buy a car for N150,000. How much does he need to deposit?', '[{"label": "A", "text": "N112,000.50", "isCorrect": false}, {"label": "B", "text": "N96,000.00", "isCorrect": false}, {"label": "C", "text": "N85,714.28", "isCorrect": false}, {"label": "D", "text": "N76,800.00", "isCorrect": true}]'::jsonb, 'D', 'P(1.25)³ = 150,000, so P = 150,000/1.953125 = N76,800.00.', 'live', '{"totalAttempts": 0, "correctCount": 0, "avgResponseTimeMs": 0, "distractorSelectionCounts": {}}'::jsonb),
('mathematics_0062', 'Mathematics', 'Measures of dispersion', 'Standard Deviation of a Linear Data Set', NULL, '[{"weight": 1, "conceptId": "r3pe29"}]'::jsonb, '{}', 3, 'application', 90, 'low', 'heavy', '[{"option": "B", "explanation": "2x results from taking the mean deviation-style average of absolute deviations without squaring, then miscalculating.", "misconceptionId": "formula_recall_error"}, {"option": "C", "explanation": "x results from a careless simplification of √(2x²) that drops the √2 factor.", "misconceptionId": "arithmetic_slip"}, {"option": "D", "explanation": "3x mistakes the mean of the data set (3x) for the spread/variability measure being asked for.", "misconceptionId": "confused_similar_concepts"}]'::jsonb, '{}', 'jamb_past_question', 2000, 'JAMB', '{}', 'The variance of x, 2x, 3x, 4x and 5x is', '[{"label": "A", "text": "x√2", "isCorrect": true}, {"label": "B", "text": "2x", "isCorrect": false}, {"label": "C", "text": "x", "isCorrect": false}, {"label": "D", "text": "3x", "isCorrect": false}]'::jsonb, 'A', 'Mean of x,2x,3x,4x,5x is 3x. Squared deviations are 4x²,x²,0,x²,4x², summing to 10x²; dividing by 5 gives a variance of 2x², whose square root (the standard deviation) is x√2 — the value matching the given options.', 'live', '{"totalAttempts": 0, "correctCount": 0, "avgResponseTimeMs": 0, "distractorSelectionCounts": {}}'::jsonb),
('mathematics_0063', 'Mathematics', 'Applications of differentiation', 'Maximizing a Profit Function', NULL, '[{"weight": 1, "conceptId": "gd8afp"}]'::jsonb, '{}', 2, 'application', 90, 'low', 'moderate', '[{"option": "A", "explanation": "4 results from an arithmetic slip while solving 10-2x=0.", "misconceptionId": "arithmetic_slip"}, {"option": "C", "explanation": "6 results from a sign error, solving 10+2x=0 style reasoning incorrectly.", "misconceptionId": "sign_error"}, {"option": "D", "explanation": "7 doesn''t correspond to setting the derivative to zero at all, suggesting a guess rather than calculus.", "misconceptionId": "guessed_no_reasoning"}]'::jsonb, '{}', 'jamb_past_question', 2000, 'JAMB', '{}', 'A trader realizes 10x - x\(^2\) naira profit from the sale of x bags on corn. How many bags will give him the desired profit?', '[{"label": "A", "text": "4", "isCorrect": false}, {"label": "B", "text": "5", "isCorrect": true}, {"label": "C", "text": "6", "isCorrect": false}, {"label": "D", "text": "7", "isCorrect": false}]'::jsonb, 'B', 'Profit P(x)=10x-x² is maximized where dP/dx=10-2x=0, giving x=5 bags.', 'live', '{"totalAttempts": 0, "correctCount": 0, "avgResponseTimeMs": 0, "distractorSelectionCounts": {}}'::jsonb),
('mathematics_0064', 'Mathematics', 'Circles', 'Circle Theorems (Chord Perpendicular to a Diameter)', NULL, '[{"weight": 1, "conceptId": "k054nz"}]'::jsonb, '{}', 3, 'application', 90, 'low', 'heavy', '[{"option": "A", "explanation": "32cm results from simply adding EG and NH (24+8) instead of applying the correct chord-diameter relation.", "misconceptionId": "formula_recall_error"}, {"option": "C", "explanation": "20cm results from using EG (not half of it) directly in the geometric-mean relation.", "misconceptionId": "formula_recall_error"}, {"option": "D", "explanation": "16cm results from doubling NH instead of correctly computing FN from the geometric-mean relation.", "misconceptionId": "confused_similar_concepts"}]'::jsonb, '{}', 'jamb_past_question', 2000, 'JAMB', '{}', 'In the diagram, EFGH is a circle centre O. FH is a diameter and GE is a chord which meets FH at right angle at the point N. If NH = 8cm and EG = 24cm, calculate FH', '[{"label": "A", "text": "32cm", "isCorrect": false}, {"label": "B", "text": "26cm", "isCorrect": true}, {"label": "C", "text": "20cm", "isCorrect": false}, {"label": "D", "text": "16cm", "isCorrect": false}]'::jsonb, 'B', 'Since GE⊥FH at N, EN=NG=EG/2=12cm. By the geometric-mean relation for a chord perpendicular to a diameter, EN²=FN×NH, so FN=144/8=18cm. Thus FH=FN+NH=18+8=26cm.', 'live', '{"totalAttempts": 0, "correctCount": 0, "avgResponseTimeMs": 0, "distractorSelectionCounts": {}}'::jsonb),
('mathematics_0065', 'Mathematics', 'Measures of dispersion', 'Mean Deviation', NULL, '[{"weight": 1, "conceptId": "dkyayq"}]'::jsonb, '{}', 3, 'application', 90, 'low', 'heavy', '[{"option": "A", "explanation": "0 results from forgetting to take absolute values, letting positive and negative deviations cancel out.", "misconceptionId": "sign_error"}, {"option": "B", "explanation": "2 results from dividing the total absolute deviation by the wrong count (6 instead of 4).", "misconceptionId": "arithmetic_slip"}, {"option": "D", "explanation": "4 mistakes the mean of the data set itself for the mean deviation.", "misconceptionId": "confused_similar_concepts"}]'::jsonb, '{}', 'jamb_past_question', 2000, 'JAMB', '{}', 'If the mean of the numbers 0, (x+2), (3x+6), and (4x+8) is 4, find their mean deviation.', '[{"label": "A", "text": "0", "isCorrect": false}, {"label": "B", "text": "2", "isCorrect": false}, {"label": "C", "text": "3", "isCorrect": true}, {"label": "D", "text": "4", "isCorrect": false}]'::jsonb, 'C', 'Setting the mean (8x+16)/4=4 gives x=0, so the values are 0,2,6,8 (mean 4). Mean deviation = (|0-4|+|2-4|+|6-4|+|8-4|)/4 = (4+2+2+4)/4 = 3.', 'live', '{"totalAttempts": 0, "correctCount": 0, "avgResponseTimeMs": 0, "distractorSelectionCounts": {}}'::jsonb),
('mathematics_0066', 'Mathematics', 'Polynomials', 'Finding Coefficients from Known Factors', NULL, '[{"weight": 1, "conceptId": "3s195j"}]'::jsonb, '{}', 3, 'application', 90, 'low', 'heavy', '[{"option": "B", "explanation": "1/2, 1, 1/2 comes from a sign error on ''a'', taking a=1/2 instead of -1/2 while keeping b and c the same.", "misconceptionId": "sign_error"}, {"option": "C", "explanation": "1/2, 1, -1/2 comes from the same sign error on ''a'' combined with a sign error on ''c'' as well.", "misconceptionId": "sign_error"}, {"option": "D", "explanation": "1/2, -1, 1/2 comes from the sign error on ''a'' combined with a sign error on ''b''.", "misconceptionId": "sign_error"}]'::jsonb, '{}', 'jamb_past_question', 2000, 'JAMB', '{}', 'if (x - 1), (x + 1) and (x - 2) are factors of the polynomial ax\(^3\) + bx\(^2\) + cx - 1, find a, b, c in that order.', '[{"label": "A", "text": "-1/2, 1., 1/2", "isCorrect": true}, {"label": "B", "text": "1/2, 1, 1/2", "isCorrect": false}, {"label": "C", "text": "1/2, 1, -1/2", "isCorrect": false}, {"label": "D", "text": "1/2, -1, 1/2", "isCorrect": false}]'::jsonb, 'A', 'Since (x-1)(x+1)(x-2) are all factors of the cubic, ax³+bx²+cx-1 = a(x-1)(x+1)(x-2) = a(x³-2x²-x+2). Matching the constant term: 2a=-1, so a=-1/2, giving b=-2a=1 and c=-a=1/2.', 'live', '{"totalAttempts": 0, "correctCount": 0, "avgResponseTimeMs": 0, "distractorSelectionCounts": {}}'::jsonb),
('mathematics_0067', 'Mathematics', 'Coordinate geometry', 'Intersection of a Circle and a Line', NULL, '[{"weight": 1, "conceptId": "msnd8d"}]'::jsonb, '{}', 3, 'application', 90, 'low', 'heavy', '[{"option": "B", "explanation": "(1,2) does not even lie on the line y=x, so it cannot be a valid intersection point.", "misconceptionId": "arithmetic_slip"}, {"option": "C", "explanation": "(0,0) is not on the circle (0²+0²=0≠2), incorrectly assuming the circle passes through the origin.", "misconceptionId": "misunderstood_terminology"}, {"option": "D", "explanation": "(√2,√2) does not lie on the circle either (its squared distance from the origin is 4, not 2) — a common substitution slip.", "misconceptionId": "arithmetic_slip"}]'::jsonb, '{}', 'jamb_past_question', 2000, 'JAMB', '{}', 'A predator moves in a circle of radius √2 centre (0,0), while a prey moves along the line y = x. If 0 \(\leq\) x \(\leq\) 2, at which point(s) will they meet?', '[{"label": "A", "text": "(1,1) only", "isCorrect": true}, {"label": "B", "text": "(1,1) and (1,2)", "isCorrect": false}, {"label": "C", "text": "(0,0) and (1,1)", "isCorrect": false}, {"label": "D", "text": "(√2,√2) only", "isCorrect": false}]'::jsonb, 'A', 'Substituting y=x into x²+y²=2 gives 2x²=2, so x=±1. Restricting to 0≤x≤2 leaves only x=1, giving the point (1,1).', 'live', '{"totalAttempts": 0, "correctCount": 0, "avgResponseTimeMs": 0, "distractorSelectionCounts": {}}'::jsonb),
('mathematics_0068', 'Mathematics', 'Trigonometric functions', 'Bearings (Resultant Displacement)', NULL, '[{"weight": 1, "conceptId": "udd467"}]'::jsonb, '{}', 3, 'application', 90, 'low', 'heavy', '[{"option": "A", "explanation": "S90°E incorrectly assumes the resultant displacement has no northward component at all.", "misconceptionId": "misread_graph"}, {"option": "B", "explanation": "N40° simply repeats the bearing of the second leg, ignoring the first leg''s contribution entirely.", "misconceptionId": "missing_prerequisite"}, {"option": "C", "explanation": "S95°E incorrectly places the resultant south of the starting point instead of north.", "misconceptionId": "sign_error"}]'::jsonb, '{}', 'jamb_past_question', 2000, 'JAMB', '{}', 'A ship sails a distance of 50km in the direction S50ºE and then sails in the distance of 50km in the direction N40ºE. Find the bearing of the ship from its original position.', '[{"label": "A", "text": "S90\\(^0\\)E", "isCorrect": false}, {"label": "B", "text": "N40\\(^0\\)", "isCorrect": false}, {"label": "C", "text": "S95\\(^0\\)E", "isCorrect": false}, {"label": "D", "text": "N85\\(^0\\)E", "isCorrect": true}]'::jsonb, 'D', 'Resolving both legs into north/east components (S50°E=bearing 130°, N40°E=bearing 40°) and summing gives a resultant displacement whose bearing works out to approximately N85°E.', 'live', '{"totalAttempts": 0, "correctCount": 0, "avgResponseTimeMs": 0, "distractorSelectionCounts": {}}'::jsonb),
('mathematics_0069', 'Mathematics', 'Arithmetic progression', 'Common Difference from Two Terms', NULL, '[{"weight": 1, "conceptId": "kd6fle"}]'::jsonb, '{}', 3, 'application', 90, 'low', 'heavy', '[{"option": "A", "explanation": "19x-17y results from adding the two given terms instead of subtracting them.", "misconceptionId": "sign_error"}, {"option": "B", "explanation": "8x-4y is just the difference of the two given terms without dividing by 6 (the number of steps between them).", "misconceptionId": "formula_recall_error"}, {"option": "D", "explanation": "2x drops the y-terms entirely, an arithmetic slip while simplifying.", "misconceptionId": "arithmetic_slip"}]'::jsonb, '{}', 'jamb_past_question', 2000, 'JAMB', '{}', 'The 3rd term of an A.P is 4x - 2y and the 9th term is 10x - 8y. Find the common difference.', '[{"label": "A", "text": "19x - 17y", "isCorrect": false}, {"label": "B", "text": "8x - 4y", "isCorrect": false}, {"label": "C", "text": "x - y", "isCorrect": true}, {"label": "D", "text": "2x", "isCorrect": false}]'::jsonb, 'C', 'The 9th term minus the 3rd term equals 6 times the common difference: (10x-8y)-(4x-2y)=6x-6y=6d, so d=x-y.', 'live', '{"totalAttempts": 0, "correctCount": 0, "avgResponseTimeMs": 0, "distractorSelectionCounts": {}}'::jsonb),
('mathematics_0070', 'Mathematics', 'Loci', 'Locus of a Point Moving Parallel to a Line', NULL, '[{"weight": 1, "conceptId": "epzhpc"}]'::jsonb, '{}', 3, 'application', 90, 'low', 'heavy', '[{"option": "A", "explanation": "310° results from taking the reflex angle instead of the standard interior angle.", "misconceptionId": "misread_graph"}, {"option": "C", "explanation": "80° results from adding 30° incorrectly instead of applying the co-interior angle relationship.", "misconceptionId": "arithmetic_slip"}, {"option": "D", "explanation": "50° simply repeats the given angle VUS, mistaking it for angle UST via the (incorrect) alternate-angle rule for this configuration.", "misconceptionId": "confused_similar_concepts"}]'::jsonb, '{}', 'jamb_past_question', 2000, 'JAMB', '{}', 'P is a point on one side of the straight line UV and P moves in the same direction as UV. If the straight line ST is on the locus of P and angle VUS = 50°, find angle UST.', '[{"label": "A", "text": "310°", "isCorrect": false}, {"label": "B", "text": "130°", "isCorrect": true}, {"label": "C", "text": "80°", "isCorrect": false}, {"label": "D", "text": "50°", "isCorrect": false}]'::jsonb, 'B', 'Since P''s locus (line ST) is parallel to UV, transversal US creates co-interior (allied) angles with the parallel lines at U and S, so angle UST = 180° - angle VUS = 180° - 50° = 130°.', 'live', '{"totalAttempts": 0, "correctCount": 0, "avgResponseTimeMs": 0, "distractorSelectionCounts": {}}'::jsonb),
('mathematics_0071', 'Mathematics', 'Matrices and determinants', 'Determinant of a 3x3 Matrix', NULL, '[{"weight": 1, "conceptId": "f07uqn"}]'::jsonb, '{}', 3, 'application', 90, 'low', 'heavy', '[{"option": "A", "explanation": "-4, 2, 3 flips the sign of the first root and one other, from a sign error while factoring.", "misconceptionId": "sign_error"}, {"option": "C", "explanation": "-4, -2, -3 flips the sign of every root, mistakenly solving (t+4)(t+3)(t-2)=0 instead.", "misconceptionId": "sign_error"}, {"option": "D", "explanation": "0, 2, 3 results from misreading the constant term of the quadratic factor as 0 instead of -6.", "misconceptionId": "arithmetic_slip"}]'::jsonb, '{}', 'jamb_past_question', 2000, 'JAMB', '{}', 'Find the values of t for which the determinant of the matrix \(\begin{pmatrix}t-4 & 0 & 0\\ -1 & t+1 & 1\\3 & 4 & t-2\end{pmatrix}\) is zero.', '[{"label": "A", "text": "-4, 2, 3.", "isCorrect": false}, {"label": "B", "text": "4, -2, 3", "isCorrect": true}, {"label": "C", "text": "-4, -2, -3", "isCorrect": false}, {"label": "D", "text": "0, 2, 3", "isCorrect": false}]'::jsonb, 'B', 'Expanding along the first row (which has two zeros): det = (t-4)[(t+1)(t-2)-4] = (t-4)(t²-t-6) = (t-4)(t-3)(t+2). Setting this to zero gives t=4, 3, -2.', 'live', '{"totalAttempts": 0, "correctCount": 0, "avgResponseTimeMs": 0, "distractorSelectionCounts": {}}'::jsonb),
('mathematics_0072', 'Mathematics', 'Sets', 'Set Difference and Intersection', NULL, '[{"weight": 1, "conceptId": "upqzit"}]'::jsonb, '{}', 2, 'application', 90, 'low', 'moderate', '[{"option": "A", "explanation": "{1,x} is P-Q itself, forgetting to then intersect with R.", "misconceptionId": "missing_prerequisite"}, {"option": "B", "explanation": "{x,y} wrongly includes y, which isn''t in P-Q at all.", "misconceptionId": "confused_similar_concepts"}, {"option": "D", "explanation": "The empty set results from wrongly concluding P-Q and R share no elements, overlooking that x is common to both.", "misconceptionId": "arithmetic_slip"}]'::jsonb, '{}', 'jamb_past_question', 2000, 'JAMB', '{}', 'Let P = {1, 2, u, v, w, x}; Q = {2, 3, u, v, w, 5, 6, y} and R = {2, 3, 4, v, x, y}. Determine (P-Q) ∩ R', '[{"label": "A", "text": "{1, x}", "isCorrect": false}, {"label": "B", "text": "{x y}", "isCorrect": false}, {"label": "C", "text": "{x}", "isCorrect": true}, {"label": "D", "text": "ɸ", "isCorrect": false}]'::jsonb, 'C', 'P-Q removes every element of P that also appears in Q (2,u,v,w), leaving {1,x}. Intersecting {1,x} with R={2,3,4,v,x,y}: only x is in R, so (P-Q)∩R = {x}.', 'live', '{"totalAttempts": 0, "correctCount": 0, "avgResponseTimeMs": 0, "distractorSelectionCounts": {}}'::jsonb),
('mathematics_0073', 'Mathematics', 'Permutations and combinations', 'Combinations with a Minimum-of-Each-Group Constraint', NULL, '[{"weight": 1, "conceptId": "3uea3g"}]'::jsonb, '{}', 3, 'application', 90, 'low', 'heavy', '[{"option": "A", "explanation": "15 results from only counting the 2-men-1-woman case (C(5,2)×C(3,1)) and omitting the 1-man-2-women case.", "misconceptionId": "missing_prerequisite"}, {"option": "B", "explanation": "28 results from only counting the 1-man-2-women case (C(5,1)×C(3,2)) and omitting the 2-men-1-woman case.", "misconceptionId": "missing_prerequisite"}, {"option": "C", "explanation": "30 results from an arithmetic slip while adding the two valid combination cases together.", "misconceptionId": "arithmetic_slip"}]'::jsonb, '{}', 'jamb_past_question', 2000, 'JAMB', '{}', 'In how many ways can a delegation of 3 be chosen from among 5 men and 3 women, if at least one man and at least one woman must be included?', '[{"label": "A", "text": "15", "isCorrect": false}, {"label": "B", "text": "28", "isCorrect": false}, {"label": "C", "text": "30", "isCorrect": false}, {"label": "D", "text": "45", "isCorrect": true}]'::jsonb, 'D', 'Total ways to choose 3 from 8 is C(8,3)=56. Subtracting the all-men case C(5,3)=10 and the all-women case C(3,3)=1 gives 56-10-1=45.', 'live', '{"totalAttempts": 0, "correctCount": 0, "avgResponseTimeMs": 0, "distractorSelectionCounts": {}}'::jsonb),
('mathematics_0074', 'Mathematics', 'Number bases', 'Base Conversion and Solving for an Unknown Base', NULL, '[{"weight": 1, "conceptId": "e8n6qi"}]'::jsonb, '{}', 3, 'application', 90, 'low', 'heavy', '[{"option": "B", "explanation": "8 results from a sign or arithmetic slip while solving the quadratic 3x²+4x-175=0.", "misconceptionId": "arithmetic_slip"}, {"option": "C", "explanation": "9 results from miscalculating 256 in base 7 (e.g. forgetting to multiply the leading digit by 7², giving a smaller decimal value and a different quadratic root).", "misconceptionId": "unit_conversion_error"}, {"option": "D", "explanation": "10 results from treating ''256'' as if it were already in base 10 rather than converting it from base 7 first.", "misconceptionId": "unit_conversion_error"}]'::jsonb, '{}', 'jamb_past_question', 2000, 'JAMB', '{}', 'If 314\(_{10}\) - 256\(_7\) = 340\(_x\), find x.', '[{"label": "A", "text": "7", "isCorrect": true}, {"label": "B", "text": "8", "isCorrect": false}, {"label": "C", "text": "9", "isCorrect": false}, {"label": "D", "text": "10", "isCorrect": false}]'::jsonb, 'A', '256 in base 7 = 2(49)+5(7)+6 = 139 in decimal. 314-139=175. Writing 175 as ''340'' in base x: 3x²+4x=175, so 3x²+4x-175=0, which factors/solves to x=7 (checking: 3(49)+4(7)=147+28=175 ✓).', 'live', '{"totalAttempts": 0, "correctCount": 0, "avgResponseTimeMs": 0, "distractorSelectionCounts": {}}'::jsonb),
('mathematics_0075', 'Mathematics', 'Number bases', 'Solving for an Unknown Digit in a Base Subtraction', NULL, '[{"weight": 1, "conceptId": "wepxsk"}]'::jsonb, '{}', 3, 'application', 90, 'low', 'heavy', '[{"option": "A", "explanation": "2 results from an arithmetic slip while simplifying the linear equation in P.", "misconceptionId": "arithmetic_slip"}, {"option": "B", "explanation": "3 results from a similar arithmetic slip in combining the P-terms across the equation.", "misconceptionId": "arithmetic_slip"}, {"option": "C", "explanation": "4 is close to the correct value but results from a small arithmetic error when isolating P.", "misconceptionId": "arithmetic_slip"}]'::jsonb, '{}', 'jamb_past_question', 2000, 'JAMB', '{}', 'If \(P344_{6} - 23P2_{6} = 2PP2_{6}\), find the value of the digit P.', '[{"label": "A", "text": "2", "isCorrect": false}, {"label": "B", "text": "3", "isCorrect": false}, {"label": "C", "text": "4", "isCorrect": false}, {"label": "D", "text": "5", "isCorrect": true}]'::jsonb, 'D', 'Converting each base-6 numeral to an equation in P: P344₆-23P2₆=2PP2₆ becomes (216P+136)-(542+6P)=(434+42P), which simplifies to 168P=840, so P=5 (verified: 5344₆-2352₆=1216-572=644=2552₆).', 'live', '{"totalAttempts": 0, "correctCount": 0, "avgResponseTimeMs": 0, "distractorSelectionCounts": {}}'::jsonb);